draw(A--B--C--D--cycle,black+linewidth(0.8)); draw(A--H--cycle,black+linewidth(0.68));
L=A+B-H;  dot(L,3bp+blue); label(" $L$ ",L,SW); draw(A--L--B--cycle, black+linewidth(0.48));
P=2*M-K;  dot(P,3bp+blue); label(" $P$ ",P,NE); draw(A--P--B--cycle,black+linewidth(0.48));
