\fill[red!5!white] (0,0)--(0,3)--(3,3)--(3,2)--(1,2)--(1,0)--cycle;
\foreach \i in {0,1,2,3} \draw[blue,thick] (0,\i)--(3,\i); \foreach \i in {0,1,2,3} \draw[blue,thick] (\i,0)--(\i,3);
\node at (1.5,0.5) { $1$ }; \node at (2.5,0.5) { $1$ }; \node at (2.5,1.5) { $1$ }; 
